<script lang="ts">let {data}=$props(); let e=$derived(data.snapshot.evaluation); const pct=(n:number)=>`${(n*100).toFixed(1)}%`; const rows=$derived([['Precision',pct(e.driftrecon.precision),pct(e.baseline.precision)],['Recall',pct(e.driftrecon.recall),pct(e.baseline.recall)],['Payout coverage',pct(e.driftrecon.payoutCoverage),pct(e.baseline.payoutCoverage)],['False auto-match rate',pct(e.driftrecon.falseAutoMatchRate),pct(e.baseline.falseAutoMatchRate)],['Human review',e.driftrecon.humanReviewCount,e.baseline.humanReviewCount]]);</script>
<svelte:head><title>Evaluation · DriftRecon</title></svelte:head><main class="shell workspace"><p class="eyebrow">Runtime results, not hard-coded claims</p><h1 class="title">Evaluation</h1><p class="lede">Compare the current DriftRecon run with the same-period baseline against held-out ground truth.</p><table class="table section"><thead><tr><th>Metric</th><th>DriftRecon</th><th>Baseline</th></tr></thead><tbody>{#each rows as row}<tr><td>{row[0]}</td><td class="mono"><strong>{row[1]}</strong></td><td class="mono">{row[2]}</td></tr>{/each}</tbody></table></main>
